def dynamic_viscosity(T):
    """Dynamic viscosity of water (Pa s), Vogel equation with T in kelvin."""
    T_K = T + 273.15
    return 2.414e-5 * 10 ** (247.8 / (T_K - 140.0))


def density(T):
    """Density of water (kg/m^3), Kell correlation."""
    return 1000.0 * (1 - (T + 288.9414) / (508929.2 * (T + 68.12963)) * (T - 3.9863) ** 2)


def viscosity(T):
    """Kinematic viscosity of water (m^2/s)."""
    return dynamic_viscosity(T) / density(T)

